// Generate UUID without crypto module
function generateUUID() {
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c === "x" ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const input = $input.first();
const json = input.json || {};
const body = json.body || json;

// Get metadata from request
const source = body.source || 'handbook';
const title = body.title || 'Help Document';

// Check for base64 data in JSON body
const base64Data = body.data;
const fileName = body.filename || body.fileName || 'document.pdf';
const mimeType = body.mimeType || 'application/pdf';

// Determine file type
const ext = fileName.split('.').pop().toLowerCase();
const isPdf = ext === 'pdf' || mimeType === 'application/pdf';

// Generate job ID
const jobId = generateUUID();

// If we have base64 data, convert it to binary properly
if (base64Data) {
  const buffer = Buffer.from(base64Data, 'base64');
  const binaryData = await this.helpers.prepareBinaryData(
    buffer,
    fileName,
    mimeType
  );
  return [{
    json: {
      jobId,
      source,
      title,
      fileName,
      isPdf,
      startedAt: new Date().toISOString()
    },
    binary: {
      data: binaryData
    }
  }];
} else if (input.binary && Object.keys(input.binary).length > 0) {
  // Use existing binary from multipart/form-data upload
  const binaryKey = Object.keys(input.binary)[0];
  const binFile = input.binary[binaryKey];
  const binFileName = binFile.fileName || fileName;
  const binExt = binFileName.split('.').pop().toLowerCase();
  const binIsPdf = binExt === 'pdf' || (binFile.mimeType || '').includes('pdf');
  return [{
    json: {
      jobId,
      source,
      title,
      fileName: binFileName,
      isPdf: binIsPdf,
      startedAt: new Date().toISOString()
    },
    binary: { data: input.binary[binaryKey] }
  }];
} else {
  throw new Error('No file provided. Send either base64-encoded "data" field or upload via multipart/form-data.');
}

// Read text/markdown file from binary and split into chunks
const input = $input.first();
const binaryKey = Object.keys(input.binary)[0];
const binaryData = input.binary[binaryKey];

// Get the text content from binary
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const text = buffer.toString('utf-8');

if (!text || text.trim().length === 0) {
  throw new Error('File is empty or could not be read as text.');
}

// Chunk the text (1000 chars with 200 overlap, similar to typical RAG chunking)
const CHUNK_SIZE = 1000;
const CHUNK_OVERLAP = 200;
const chunks = [];
let start = 0;

while (start < text.length) {
  let end = start + CHUNK_SIZE;

  // Try to break at a paragraph or sentence boundary
  if (end < text.length) {
    // Look for paragraph break
    const paraBreak = text.lastIndexOf('\n\n', end);
    if (paraBreak > start + CHUNK_SIZE * 0.5) {
      end = paraBreak + 2;
    } else {
      // Look for sentence break
      const sentBreak = text.lastIndexOf('. ', end);
      if (sentBreak > start + CHUNK_SIZE * 0.5) {
        end = sentBreak + 2;
      }
    }
  } else {
    end = text.length;
  }

  const chunk = text.slice(start, end).trim();
  if (chunk.length > 0) {
    chunks.push({
      json: {
        text: chunk,
        numpages: 0
      }
    });
  }

  start = end - CHUNK_OVERLAP;
  if (start >= text.length) break;
}

return chunks;

const items = $input.all();
const jobConfig = $('Validate Input').first().json;

const enrichedDocs = items.map((item, index) => {
  const doc = item.json;

  return {
    json: {
      pageContent: doc.text || doc.pageContent || '',
      metadata: {
        source: jobConfig.source,
        title: jobConfig.title,
        chunkIndex: index,
        fileName: jobConfig.fileName,
        numPages: doc.numpages || 0,
        loadedAt: new Date().toISOString()
      }
    }
  };
});

return enrichedDocs;

const items = $input.all();
const jobConfig = $('Validate Input').first().json;

const result = {
  success: true,
  jobId: jobConfig.jobId,
  source: jobConfig.source,
  title: jobConfig.title,
  fileName: jobConfig.fileName,
  documentsLoaded: items.length,
  processedAt: new Date().toISOString(),
  processingDuration: Date.now() - new Date(jobConfig.startedAt).getTime(),
  message: `Successfully loaded ${items.length} document chunks from ${jobConfig.fileName}`
};

return [{ json: result }];

